<?php $adminTitle='Thêm/Sửa phim';require __DIR__.'/_header.php';$id=(int)($_GET['id']??0);$m=$id?movie_by_id($id):null;if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');if(!$slug)$slug=preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$name)?:$name));$data=['name'=>$name,'slug'=>trim($slug,'-'),'origin_name'=>trim($_POST['origin_name']??''),'thumb_url'=>trim($_POST['thumb_url']??''),'poster_url'=>trim($_POST['poster_url']??''),'type'=>trim($_POST['type']??''),'status'=>trim($_POST['status']??''),'year'=>(int)($_POST['year']??0),'time'=>trim($_POST['time']??''),'quality'=>trim($_POST['quality']??''),'lang'=>trim($_POST['lang']??''),'categories'=>trim($_POST['categories']??''),'countries'=>trim($_POST['countries']??''),'description'=>trim($_POST['description']??''),'director'=>trim($_POST['director']??''),'actors'=>trim($_POST['actors']??''),'trailer_url'=>trim($_POST['trailer_url']??'')];if($id){$du=db()->prepare('SELECT id FROM movies WHERE slug=? AND id<>? LIMIT 1');$du->execute([$data['slug'],$id]);if($du->fetchColumn()!==false){$data['slug']=$data['slug'].'-'.time();}$sql='UPDATE movies SET name=:name,slug=:slug,origin_name=:origin_name,thumb_url=:thumb_url,poster_url=:poster_url,type=:type,status=:status,year=:year,time=:time,quality=:quality,lang=:lang,categories=:categories,countries=:countries,description=:description,director=:director,actors=:actors,trailer_url=:trailer_url,source_type="manual",updated_at=NOW() WHERE id=:id';$data['id']=$id;db()->prepare($sql)->execute($data);}else{$base=$data['slug'];$n=0;$check=db()->prepare('SELECT id FROM movies WHERE slug=? LIMIT 1');do{$slug=$n?$base.'-'.$n:$base;$check->execute([$slug]);$n++;}while($check->fetchColumn()!==false);$data['slug']=$slug;$sql='INSERT INTO movies(name,slug,origin_name,thumb_url,poster_url,type,status,year,time,quality,lang,categories,countries,description,director,actors,trailer_url,source_type,updated_at) VALUES(:name,:slug,:origin_name,:thumb_url,:poster_url,:type,:status,:year,:time,:quality,:lang,:categories,:countries,:description,:director,:actors,:trailer_url,"manual",NOW())';db()->prepare($sql)->execute($data);$id=(int)db()->lastInsertId();}header('Location:episodes.php?id='.$id);exit;}$m=$m?:array_fill_keys(['name','slug','origin_name','thumb_url','poster_url','type','status','year','time','quality','lang','categories','countries','description','director','actors','trailer_url'],'');?><div class="admin-head"><div><small>EDITOR</small><h1><?=$id?'Chỉnh sửa phim':'Thêm phim thủ công'?></h1></div></div><section class="admin-card"><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><label>Tên phim<input name="name" value="<?=e($m['name'])?>" required></label><label>Slug<input name="slug" value="<?=e($m['slug'])?>"></label><label>Tên gốc<input name="origin_name" value="<?=e($m['origin_name'])?>"></label><label>Poster URL<input name="poster_url" value="<?=e($m['poster_url'])?>"></label><label>Thumb/Backdrop URL<input name="thumb_url" value="<?=e($m['thumb_url'])?>"></label><label>Loại phim<input name="type" value="<?=e($m['type'])?>" placeholder="Phim lẻ / Phim bộ / Hoạt hình"></label><label>Trạng thái<input name="status" value="<?=e($m['status'])?>"></label><label>Năm<input type="number" name="year" value="<?=e((string)$m['year'])?>"></label><label>Thời lượng<input name="time" value="<?=e($m['time'])?>"></label><label>Chất lượng<input name="quality" value="<?=e($m['quality'])?>"></label><label>Ngôn ngữ<input name="lang" value="<?=e($m['lang'])?>"></label><label>Thể loại (phân cách bằng dấu phẩy)<input name="categories" value="<?=e($m['categories'])?>"></label><label>Quốc gia<input name="countries" value="<?=e($m['countries'])?>"></label><label>Đạo diễn<input name="director" value="<?=e($m['director'])?>"></label><label>Diễn viên<input name="actors" value="<?=e($m['actors'])?>"></label><label>Trailer URL<input name="trailer_url" value="<?=e($m['trailer_url'])?>"></label><label>Mô tả<textarea name="description"><?=e($m['description'])?></textarea></label><div class="actions"><button class="btn primary">Lưu phim</button><a class="btn" href="movies.php">Hủy</a></div></form></section><?php require __DIR__.'/_footer.php';?>
